using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [Column(0)]
    public string Subject { get; set; } = string.Empty;

    [Column(1)]
    public string Description { get; set; } = string.Empty;

    [Column(2)]
    public float Priority { get; set; }

    [Column(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedLabel { get; set; } = string.Empty;

    [ColumnName("Score")]
    public float[] Score { get; set; } = [];
}

public record ModelMetrics(double MacroAccuracy, double MicroAccuracy, double LogLoss);

public record TicketRequest(string Subject, string Description, float Priority);

public record TicketClassificationResponse(string PredictedCategory, float Confidence);

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public interface IModelTrainingService
{
    ModelMetrics TrainAndEvaluate();
}

public class ModelTrainingService : IModelTrainingService
{
    private readonly ILogger<ModelTrainingService> _logger;
    private readonly string _dataPath;
    private readonly string _modelPath;

    public ModelTrainingService(ILogger<ModelTrainingService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        var contentRoot = env.ContentRootPath;
        _dataPath = Path.Combine(contentRoot, "Data", "tickets.csv");
        _modelPath = Path.Combine(contentRoot, "Data", "TicketClassifierModel.zip");
    }

    public ModelMetrics TrainAndEvaluate()
    {
        var mlContext = new MLContext(seed: 42);

        var data = mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation("MacroAccuracy: {MacroAccuracy}", metrics.MacroAccuracy);
        _logger.LogInformation("MicroAccuracy: {MicroAccuracy}", metrics.MicroAccuracy);
        _logger.LogInformation("LogLoss: {LogLoss}", metrics.LogLoss);

        mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {ModelPath}", _modelPath);

        return new ModelMetrics(metrics.MacroAccuracy, metrics.MicroAccuracy, metrics.LogLoss);
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/tickets")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionPool;
    private readonly IModelTrainingService _trainingService;

    public TicketController(
        PredictionEnginePool<TicketData, TicketPrediction> predictionPool,
        IModelTrainingService trainingService)
    {
        _predictionPool = predictionPool;
        _trainingService = trainingService;
    }

    [HttpPost("classify")]
    public ActionResult<TicketClassificationResponse> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);
        var confidence = prediction.Score.Max();

        return Ok(new TicketClassificationResponse(prediction.PredictedLabel, confidence));
    }

    [HttpPost("train")]
    public ActionResult<ModelMetrics> Train()
    {
        var metrics = _trainingService.TrainAndEvaluate();
        return Ok(metrics);
    }
}

