var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<IModelTrainingService, ModelTrainingService>();

var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "TicketClassifierModel.zip");
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath: modelPath, watchForChanges: true);

var app = builder.Build();

if (!File.Exists(modelPath))
{
    var trainingService = app.Services.GetRequiredService<IModelTrainingService>();
    trainingService.TrainAndEvaluate();
}

app.MapControllers();
app.Run();

